<?php
declare(strict_types=1);require __DIR__.'/app/bootstrap.php';if(!is_installed())redirect('setup.php');$token=preg_replace('/[^a-f0-9]/','',$_GET['token']??'');$st=db()->prepare("SELECT d.document_type,d.title,d.status,d.signed_at,u.name professional_name,u.professional_crp,t.name tenant_name FROM clinical_documents d JOIN users u ON u.id=d.professional_id AND u.tenant_id=d.tenant_id JOIN tenants t ON t.id=d.tenant_id WHERE d.validation_token=:token LIMIT 1");$st->execute(['token'=>$token]);$d=$st->fetch();layout('Validar documento',function()use($d){?><div class="auth-form-wrap" style="min-height:100vh"><div class="auth-form card"><a class="brand" href="<?=e(url())?>"><span class="brand-mark">P</span><span>PsicoManager <b>AI</b></span></a><?php if(!$d):?><h1>Documento não localizado</h1><p>O código informado não existe.</p><?php else:?><h1><?= $d['status']==='signed'?'Documento válido':'Documento ainda não assinado'?></h1><p><strong><?=e($d['tenant_name'])?></strong><br><?=e($d['title'])?><br><?=e(ucfirst($d['document_type']))?></p><p>Profissional: <?=e($d['professional_name'])?> <?=e($d['professional_crp']?:'')?><br><?= $d['signed_at']?'Assinado em '.e(date('d/m/Y H:i',strtotime($d['signed_at']))):'Sem assinatura final'?></p><p class="help">Por privacidade, esta página não exibe nome do paciente nem conteúdo do documento.</p><?php endif?></div></div><?php },['public'=>true]);
